import { Routes, Route } from "react-router-dom";
import './style.css'

function News(){
    return (
        <p><h1>News</h1></p>
    )
}

function About(){
    return (
    <h1>Южный Федеральный Университет</h1>
    )
}

function Contacts(){
    return(
        <h1>8 800 555 35 35</h1>
    )
}

export function Main(){
    return (
        <div class='main'>
            <div class='main_container'>
            <section class='flex-center'><img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTurm1vZCbsJzvl99vIquMfNYD8t478mzD3rA&s" width={200} alt='jimin'/></section>
            <article class='flex-center'>
                <Routes>
                    <Route path='/news' element={<News />} />
                    <Route path='/about' element={<About />} />
                    <Route path='/contacts' element={<Contacts />} />
                    <Route path='*' elements={<h3>некорректная ссылка</h3>}/>
                </Routes>
            </article>
            <aside class='flex-center'>Черных Алиса Александровна</aside>
            </div>
        </div>
    )
}

export default Main;
